Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <iostream>
#include <vector>
using namespace std;

long long ones[20];

int count_ones(long long n, int i) {
    int total_ones = 0;
    while (i > 0) {
        long long block = ones[i];
        int times = n / block;
        total_ones += times * i;
        n %= block;
        if (n == 0) break;
        total_ones += min(i + count_ones(ones[i] - n, i - 1), count_ones(n, i - 1));
        break;
    }
    return total_ones;
}

int main() {
    ones[0] = 0;
    for (int i = 1; i <= 16; ++i) {
        ones[i] = ones[i - 1] * 10 + 1;
    }
    long long n;
    cin >> n;
    cout << count_ones(n, 16) << endl;
    return 0;
}
